Change(genesis='e44b01205cdace6f30ebc3c48eee515a5e1ef4d70aae9a18b591ba5f45a131a9', deps=('2369c75ac509f11e705a991dac5b6d7f2eeb9505011eb8739a0b6adc6d46ba84',), event=Authored(todo='revise-item-text', at=datetime(2026, 11, 17, 23, 5, 0), actor='maintainer', kind='todo', created=datetime(2026, 11, 17, 23, 5, 0), body='add a CLI verb that writes a new content record for an existing item, so that a revised text replaces the old one', spec=None, rationale=(), category='', waiting_on='', detail='The CLI has no verb that changes the text of an existing item: add refuses an id that exists. So a maintainer records a new text as the note of a SpecRevised at the same price, and prodrome show and the viewer still show the old body and detail. A verb that writes an Authored record with the new body and detail, and no spec, would keep the price in force, as the issue mirror does for a retitle. Price 70: the roadmap shows outdated text for every partly done item until then.', source=None, subtodos=(), notes=(), note=''))